const input = $input.first().json;
let body = (input && input.body !== undefined) ? input.body : input;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
body = body || {};
const request_text = (body.request_text || '').toString().trim();
const image_b64 = (body.image_b64 || '').toString();
const mime_type = (body.mime_type || 'image/jpeg').toString();
if (!request_text) throw new Error('request_text is required');
if (!image_b64) throw new Error('image_b64 is required');
const check_prompt = 'You are a pre-send quality check for a solo content creator who sends finished images out against different requests/briefs. What was requested: "' + request_text + '". Look at the attached image and do all of the following: (1) write a 1-2 sentence summary of what is actually shown in the image; (2) transcribe any text/words visibly baked into the image into extracted_text (use an empty string if there is none); (3) if extracted_text is non-empty, list every spelling or grammar mistake in it as an array of objects with "issue" and "suggestion" keys (use an empty array if there is no text or no mistakes); (4) decide a verdict of exactly one of "match", "partial_match", or "mismatch" for whether this image actually fulfills what was requested, and write a 1-2 sentence verdict_reason explaining why - this last step exists specifically to catch the wrong image being sent for the wrong request. Return ONLY valid JSON, no markdown fences, no commentary, with exactly these keys: summary, extracted_text, grammar_issues, verdict, verdict_reason.';
return [{ json: { request_text, image_b64, mime_type, check_prompt } }];

const res = $input.first().json;
const raw = (res.content && res.content[0] && res.content[0].text) ? res.content[0].text : '{}';
let txt = raw.trim();
if (txt.startsWith('```')) { txt = txt.substring(txt.indexOf('\n') + 1); if (txt.endsWith('```')) txt = txt.slice(0, -3); txt = txt.trim(); }
let parsed = {};
try { parsed = JSON.parse(txt); } catch (e) { parsed = {}; }

const summary = (parsed.summary || '').toString();
const extracted_text = (parsed.extracted_text || '').toString();
const grammar_issues = Array.isArray(parsed.grammar_issues) ? parsed.grammar_issues : [];
const allowedVerdicts = ['match', 'partial_match', 'mismatch'];
const verdict = allowedVerdicts.includes(parsed.verdict) ? parsed.verdict : 'partial_match';
const verdict_reason = (parsed.verdict_reason || '').toString();

return [{ json: { ok: true, summary, extracted_text, grammar_issues, verdict, verdict_reason } }];
